using UnityEngine; public class BikeController : MonoBehaviour { public float speed = 0f; public float acceleration = 12f; public float maxSpeed = 60f; public float steeringSpeed = 80f; void Update() { if (Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.UpArrow)) { speed += acceleration * Time.deltaTime; } else { speed -= acceleration * 0.5f * Time.deltaTime; } speed = Mathf.Clamp(speed, 0f, maxSpeed); float turn = Input.GetAxis("Horizontal"); transform.Translate( Vector3.forward * speed * Time.deltaTime ); transform.Rotate( Vector3.up * turn * steeringSpeed * Time.deltaTime ); } } 